/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
                      int n,
                      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

  /* Precompute 1/9 once to avoid a costly division in the inner loop.
     SCALAR_VAL makes this work correctly for both float and double. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

  /* Tile size in the i (row) dimension.
     Tiling only in i preserves the original lexicographic (i,j) order and
     therefore all Gauss–Seidel dependencies. 64 is a reasonable default
     on modern x86-64 CPUs; the min() below handles small problem sizes. */
  const int tile_i = 64;

  /* Last interior index: original loops run i,j = 1 .. _PB_N-2. */
  const int i_last = _PB_N - 2;
  const int j_last = _PB_N - 2;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++)
  {
    /* 1D blocking in the row dimension: we visit rows in the same global
       order as the original code, but grouped into contiguous bands. */
    for (int ii = 1; ii <= i_last; ii += tile_i)
    {
      const int i_max = (ii + tile_i - 1 <= i_last) ? (ii + tile_i - 1)
                                                    : i_last;

      for (i = ii; i <= i_max; i++)
      {
        /* Pointers to the three rows touched by the 3x3 stencil.
           These rows do not alias each other, and accessing them via
           row pointers improves address arithmetic and cache behavior. */
        DATA_TYPE *Ai   = A[i];
        DATA_TYPE *Aim1 = A[i-1];
        DATA_TYPE *Aip1 = A[i+1];

        /* The problem guarantees N > 2, so j_last >= 1. This guard keeps
           the logic robust even for very small instances. */
        if (j_last >= 1)
        {
          /* --- Initialize sliding windows at j = 1 --------------------
             We form 3-wide horizontal sums in the rows above and below,
             and in the current row, at columns 0,1,2. These correspond
             exactly to the 3x3 neighborhood of point (i,1). */
          DATA_TYPE s_up  = Aim1[0] + Aim1[1] + Aim1[2];
          DATA_TYPE s_mid = Ai[0]   + Ai[1]   + Ai[2];
          DATA_TYPE s_dn  = Aip1[0] + Aip1[1] + Aip1[2];

          /* First interior column update: j = 1. Semantics:
               A[i,1] ← (A[i-1,0..2] + A[i,0..2] + A[i+1,0..2]) / 9
             which matches the original kernel exactly. */
          Ai[1] = (s_up + s_mid + s_dn) * inv9;

          /* --- Main sweep: j = 2 .. j_last ---------------------------
             We slide the 3-wide windows along j for the rows i-1 and i+1,
             reusing the partial sums and only loading two new elements per
             iteration (one entering the window on the right, one leaving
             on the left). The middle row is recomputed each time to
             preserve the Gauss–Seidel update pattern:
               - A[i,j-1] is already updated,
               - A[i,j], A[i,j+1] are still from the previous state. */
          for (j = 2; j <= j_last; j++)
          {
            /* Update sums for rows i-1 and i+1 using a 3-point sliding
               window: new window [j-1, j, j+1] =
                 old window [j-2, j-1, j] plus A[*,j+1] minus A[*,j-2]. */
            s_up +=  Aim1[j+1] - Aim1[j-2];
            s_dn +=  Aip1[j+1] - Aip1[j-2];

            /* Middle row window at current (t,i,j):
               A[i,j-1] is the freshly updated value from this time step,
               while A[i,j] and A[i,j+1] are still old. */
            s_mid =  Ai[j-1] + Ai[j] + Ai[j+1];

            Ai[j] = (s_up + s_mid + s_dn) * inv9;
          }
        }
      }
    }
  }
#pragma endscop

}


