   - Strength reduction: precompute inv9 = 1.0 / 9.0 once and use a
     multiplication instead of a division in the inner loop.
   - 1D blocking (tiling) along the i dimension to improve cache
     locality over contiguous row bands while preserving the original
     Gauss–Seidel (t, i, j) execution order.
   - Sliding-window reuse along j for rows i-1 and i+1: we maintain
     3-point horizontal sums for these rows and update them as we move
     j from left to right. This reduces the number of loads per grid
     point from 9 to about 5, without changing the numerical scheme.
*/
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

  /* Replace division by 9.0 with a multiplication by its reciprocal.
     Computed once here; reused in the innermost loop. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

  /* Tile size for the i (row) dimension.
     32 works well on typical x64 caches; edge tiles are handled by
     clamping the upper bound. */
  const int tile_i = 32;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++)
  {
    /* Strip-mine / block the i-loop:
         original: for (i = 1; i <= _PB_N-2; ++i)
         tiled:    for (ii) for (i = ii; i <= i_end; ++i)
       This preserves the global (t, i, j) lexicographic order, hence
       all Gauss–Seidel dependencies. */
    for (int ii = 1; ii <= _PB_N - 2; ii += tile_i)
    {
      int i_end = ii + tile_i - 1;
      if (i_end > _PB_N - 2)
        i_end = _PB_N - 2;

      for (i = ii; i <= i_end; ++i)
      {
        /* Row pointers for faster, more cache-friendly access. */
        DATA_TYPE *Ai_prev = A[i-1];
        DATA_TYPE *Ai_cur  = A[i];
        DATA_TYPE *Ai_next = A[i+1];

        /* --- Initialize sliding 3-point windows at j = 1 -------------
           For j = 1, horizontal windows span columns 0,1,2 in rows
           i-1, i, and i+1. These are exactly the neighbors used in the
           original stencil for (i,1). */
        DATA_TYPE s_up  = Ai_prev[0] + Ai_prev[1] + Ai_prev[2];
        DATA_TYPE s_mid = Ai_cur [0] + Ai_cur [1] + Ai_cur [2];
        DATA_TYPE s_dn  = Ai_next[0] + Ai_next[1] + Ai_next[2];

        /* First interior point in the row: j = 1. */
        Ai_cur[1] = (s_up + s_mid + s_dn) * inv9;

        /* --- Main sweep: j = 2 .. _PB_N-2 ----------------------------
           j is strictly sequential, preserving the Gauss–Seidel
           dependence A[i][j-1] -> A[i][j].

           For rows i-1 and i+1 (which are not modified within this
           (t, i) row sweep), we slide a 3-point window one cell to the
           right using the recurrence:
             s_up(j) = s_up(j-1) + A[i-1][j+1] - A[i-1][j-2]
             s_dn(j) = s_dn(j-1) + A[i+1][j+1] - A[i+1][j-2]

           For the central row i, the values change in-place along j,
           so we recompute the 3-point sum directly each time:
             s_mid(j) = A[i][j-1] (new) + A[i][j] (old) + A[i][j+1] (old)

           This matches the original Gauss–Seidel scheme exactly. */
        for (j = 2; j <= _PB_N - 2; ++j)
        {
          /* Update sliding windows for rows i-1 and i+1. */
          s_up += Ai_prev[j+1] - Ai_prev[j-2];
          s_dn += Ai_next[j+1] - Ai_next[j-2];

          /* Central-row window uses the current Gauss–Seidel state. */
          s_mid = Ai_cur[j-1] + Ai_cur[j] + Ai_cur[j+1];

          Ai_cur[j] = (s_up + s_mid + s_dn) * inv9;
        }
      }
    }
  }
#pragma endscop

}


