 * then j increasing from 1 to N-2. Gauss–Seidel dependences along
 * both i and j are therefore preserved exactly.
 */
static
void kernel_seidel_2d [[gnu::flatten, gnu::noinline]] (int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

  /* Precompute 1/9 once; use multiplication instead of division. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

  /* Local aliases for the polybench loop bounds. */
  const int n_local      = _PB_N;       /* total grid size (N)         */
  const int tsteps_local = _PB_TSTEPS;  /* number of time steps        */
  const int n_inner_end  = n_local - 1; /* exclusive upper bound for i,j */

