        DATA_TYPE s_up  = Ai_prev[0] + Ai_prev[1] + Ai_prev[2];
        DATA_TYPE s_mid = Ai[0]      + Ai[1]      + Ai[2];
        DATA_TYPE s_dn  = Ai_next[0] + Ai_next[1] + Ai_next[2];

        /* First interior update: j = 1. This matches the original
         * expression using the 3x3 neighborhood centered at (i,1).
         */
        Ai[1] = (s_up + s_mid + s_dn) * inv9;

        /* --- Main sweep along the row: j = 2 .. N-2 ------------------ */
        /* For each step in j, we slide the 3-wide window one cell to
         * the right in rows i-1 and i+1:
         *   s_up(j) = s_up(j-1) + A[i-1, j+1] - A[i-1, j-2]
         *   s_dn(j) = s_dn(j-1) + A[i+1, j+1] - A[i+1, j-2]
         *
         * The central row sum s_mid is recomputed each time because it
         * mixes one newly updated value A[i, j-1] with two old values
         * A[i, j] and A[i, j+1], exactly as in the original Gauss–Seidel
         * scheme.
         */
        for (j = 2; j < n_inner_end; ++j) /* j = 2 .. N-2 */
        {
          s_up += Ai_prev[j+1] - Ai_prev[j-2];
          s_dn += Ai_next[j+1] - Ai_next[j-2];

          s_mid = Ai[j-1] + Ai[j] + Ai[j+1];

          Ai[j] = (s_up + s_mid + s_dn) * inv9;
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
