/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving Gauss–Seidel semantics):

   - Strength reduction: replace division by 9.0 with multiplication
     by its precomputed reciprocal 'inv9'.

   - 1D blocking in the i (row) dimension: we process rows in small
     contiguous tiles to improve cache locality. The global (t,i,j)
     execution order remains identical to the original code.

   - Sliding window along j for rows i-1 and i+1: reuse the horizontal
     3-point sums (s_up and s_dn) as we move the stencil one column
     to the right. This reduces memory traffic.

   - Manual unrolling by 2 of the j loop body, while keeping the
     left-to-right Gauss–Seidel dependence A[i][j-1] -> A[i][j].
*/
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i;

  /* Precompute 1.0 / 9.0 once for the whole kernel. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

  /* Tile size for the i (row) dimension. This is a tuning knob; 32
     works well on typical cache sizes for this stencil. */
  const int tile_i = 32;

  /* Last interior column index (1 .. last_col are interior). */
  const int last_col = _PB_N - 2;

  /* Upper bound for i loop: interior rows are 1 .. (_PB_N - 2). */
  const int i_limit = _PB_N - 1;

  /* If there are no interior points or no time steps, nothing to do. */
  if (last_col < 1 || _PB_TSTEPS <= 0)
    return;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; ++t)
  {
    /* 1D blocking in i: group consecutive rows into tiles.
       Order of (i,j) updates is still row-major and identical
       to the original code. */
    for (int ii = 1; ii < i_limit; ii += tile_i)
    {
      int i_end = ii + tile_i;
      if (i_end > i_limit)
        i_end = i_limit;

      for (i = ii; i < i_end; ++i)
      {
        /* Pointers to the three consecutive rows used by the stencil. */
        DATA_TYPE *row_im1 = A[i-1];
        DATA_TYPE *row_i   = A[i];
        DATA_TYPE *row_ip1 = A[i+1];

        /* --- Initialize sliding window at j = 1 ----------------------
           For j = 1 the horizontal 3-point windows are columns 0,1,2
           in rows i-1, i, and i+1. */
        DATA_TYPE s_up  = row_im1[0] + row_im1[1] + row_im1[2];
        DATA_TYPE s_mid = row_i  [0] + row_i  [1] + row_i  [2];
        DATA_TYPE s_dn  = row_ip1[0] + row_ip1[1] + row_ip1[2];

        row_i[1] = (s_up + s_mid + s_dn) * inv9;

        /* --- Main sweep: j = 2 .. last_col, unrolled by 2 ------------
           s_up and s_dn implement a 3-point sliding window along j for
           rows i-1 and i+1, respectively:
             s_* (center at j) = s_* (center at j-1)
                                   + A[*, j+1] - A[*, j-2]
           The central row sum s_mid is recomputed at each position so
           that it correctly mixes:
             - updated A[i, j-1]
             - old     A[i, j], A[i, j+1]
           exactly as in the original Gauss–Seidel scheme. */
        int j = 2;

        /* Unrolled body processes columns j and j+1 in sequence. */
        for (; j + 1 <= last_col; j += 2)
        {
          /* First point: column j. */
          s_up  += row_im1[j + 1] - row_im1[j - 2];
          s_dn  += row_ip1[j + 1] - row_ip1[j - 2];
          s_mid  = row_i[j - 1] + row_i[j] + row_i[j + 1];
          row_i[j] = (s_up + s_mid + s_dn) * inv9;

          /* Second point: column j+1. */
          int jp1 = j + 1;
          s_up  += row_im1[jp1 + 1] - row_im1[jp1 - 2];
          s_dn  += row_ip1[jp1 + 1] - row_ip1[jp1 - 2];
          s_mid  = row_i[jp1 - 1] + row_i[jp1] + row_i[jp1 + 1];
          row_i[jp1] = (s_up + s_mid + s_dn) * inv9;
        }

        /* Handle a possible last column if the interior width is not
           a multiple of the unroll factor. */
        for (; j <= last_col; ++j)
        {
          s_up  += row_im1[j + 1] - row_im1[j - 2];
          s_dn  += row_ip1[j + 1] - row_ip1[j - 2];
          s_mid  = row_i[j - 1] + row_i[j] + row_i[j + 1];
          row_i[j] = (s_up + s_mid + s_dn) * inv9;
        }
      }
    }
  }
#pragma endscop

}


